package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;
import java.time.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class TimelineReminderTest {
 final Instant now=Instant.parse("2026-10-19T00:00:00Z");
 Tournament cup(){var t=new Tournament("fixture","Reminders",TournamentFormat.ROUND_ROBIN,now);t.status=TournamentStatus.REGISTRATION;t.timeline=new TournamentTimeline(now.minusSeconds(14400),now.minusSeconds(7200),now,now.plusSeconds(3600),now.plusSeconds(3600),now.plusSeconds(4200),now.plusSeconds(4200),now.plusSeconds(5400),now.plusSeconds(6000),now.plusSeconds(9000),null);return t;}
 @Test void eachCodingWarningHasItsOwnWindowAndNeverReplaysObsoleteWarnings(){var t=cup();int[] offsets={1800,3000,3300,3540};int[] minutes={30,10,5,1};for(int i=0;i<offsets.length;i++){var due=TimelineNotificationService.due(t,now.plusSeconds(offsets[i]));var warnings=due.stream().filter(n->n.type().endsWith("_MIN_LEFT")).map(TimelineNotificationService.Notice::type);assertThat(warnings).containsExactly("TIMELINE_CODING_"+minutes[i]+"_MIN_LEFT");}assertThat(TimelineNotificationService.due(t,now.plusSeconds(3600)).stream().map(TimelineNotificationService.Notice::type)).contains("TIMELINE_CODING_ENDED","TIMELINE_VALIDATION_STARTED").noneMatch(s->s.endsWith("_MIN_LEFT"));}
 @Test void registrationCodingCheckInAndStartRemindersRespectTheirExactWindows(){var t=cup();assertThat(TimelineNotificationService.due(t,now.minusSeconds(10800)).stream().map(TimelineNotificationService.Notice::type)).contains("TIMELINE_REGISTRATION_OPENED","TIMELINE_REGISTRATION_CLOSING");assertThat(TimelineNotificationService.due(t,now.minusSeconds(1800)).stream().map(TimelineNotificationService.Notice::type)).contains("TIMELINE_CODING_STARTING");assertThat(TimelineNotificationService.due(t,now.plusSeconds(4800)).stream().map(TimelineNotificationService.Notice::type)).contains("TIMELINE_CHECK_IN_OPENED","TIMELINE_CHECK_IN_CLOSING");assertThat(TimelineNotificationService.due(t,now.plusSeconds(5400)).stream().map(TimelineNotificationService.Notice::type)).contains("TIMELINE_TOURNAMENT_STARTING").doesNotContain("TIMELINE_CHECK_IN_OPENED","TIMELINE_CHECK_IN_CLOSING");}
 @Test void terminalLifecycleAndUnpublishedDraftNeverEmitReminders(){for(var status:new TournamentStatus[]{TournamentStatus.DRAFT,TournamentStatus.RUNNING,TournamentStatus.PAUSED,TournamentStatus.RECOVERY_REQUIRED,TournamentStatus.FINISHED,TournamentStatus.CANCELLED}){var t=cup();t.status=status;assertThat(TimelineNotificationService.due(t,now)).isEmpty();}}
}
